# cycle runners
# ----------------------------------------------------------------------
def run_cycle(cfg: Config, force: bool = False):
    s = st.session_state
    now = time.time()
    stale = now - float(s.get("last_run", 0)) > max(5, cfg.refresh_seconds)
    if not force and s.get("state") is not None and not stale:
        return s["state"]
    orch = Orchestrator(cfg)
    universe = s.get("universe", FNO_UNIVERSE)

    # 0.3% proximity rows are computed from cached candles (cheap on re-runs)
    #    and handed to the alert rules BEFORE the agents evaluate them.
    try:
        _watch = approaching(zone_rows(universe, tf=cfg.zone_watch_tf,
                                       max_symbols=cfg.zone_watch_max_symbols),
                             cfg.zone_watch_pct)
    except Exception:                                                # noqa: BLE001
        _watch = []
    orch.state.zone_watch = _watch

    rules = dict(st.session_state.get("ui_rules", {}))
    with st.spinner("Agents working: ingest → derivatives → news → alerts …"):
        state = orch.run(universe, zone_timeframes=[], zone_symbols=[], run_zone=False,
                         alert_rules=rules, auto_trade=bool(st.session_state.get("ui_auto_trade", False)))
    state.zone_watch = _watch
    s["orch"], s["state"], s["last_run"] = orch, state, now
    s["zone_dirty"] = True
    return state


def zone_map_from_state(state, symbols=None) -> dict:
    """Nearest demand/supply zone per symbol across timeframes.

    Sources, in order of preference:
      1. ``state.zones`` - the Zone Agent's own multi-timeframe scan (real OHLC);
      2. a light 15m + 1d pass over the whole F&O universe, module-cached 8 min,
         so the master table has a zone for the rows outside the agent's scope.
    The closest zone wins, whichever timeframe it came from.
    """
    rows = list(getattr(state, "zones", None) or [])
    if symbols:
        try:
            from terminal.alerts.watch import zone_rows
            for tf in ("15m", "1d"):
                rows += zone_rows(list(symbols), tf=tf,
                                  max_symbols=len(symbols), ttl=480)
        except Exception:                                     # noqa: BLE001
            pass
    best: dict = {}
    for r in rows:
        sym, ltp = r.get("Symbol"), r.get("LTP") or 0
        prox = r.get("Entry (Proximal)") or r.get("Proximal") or 0
        if not sym or not ltp or not prox:
            continue
        gap = abs(float(prox) - float(ltp)) / float(ltp) * 100.0
        cur = best.get(sym)
        if cur is None or gap < cur["Gap %"]:
            best[sym] = {"Side": r.get("demand/Supply") or r.get("Side", ""),
                         "TF": r.get("tf") or r.get("TF", ""),
                         "Gap %": round(gap, 2)}
    return best


def run_zone_scan(cfg: Config):
    s = st.session_state
    state = s.get("state")
    if state is None:
        return
    tfs = s.get("ui_tfs", ["15m", "1h", "1d"])
    scope = s.get("ui_scope", "Top 40 by |AI score|")
    if scope.startswith("Top"):
        try:
            n = int(scope.split()[1])
        except Exception:
            n = 40
        syms = [f["Symbol"] for f in sorted(state.features, key=lambda f: -abs(f["Raw_Score"]))[:n]]
    elif scope == "Watchlist":
        wl = [x.strip().upper() for x in s.get("ui_watchlist", "").split(",") if x.strip()]
        syms = wl or [f["Symbol"] for f in state.features[:25]]
    else:
        syms = [f["Symbol"] for f in state.features]
    with st.spinner(f"Zone Agent scanning {len(syms)} symbols × {len(tfs)} timeframes …"):
        rep = ZoneAgent(cfg).run(state, timeframes=list(tfs), symbols=syms,
                                 max_symbols=len(syms))
        rrep = RiskAgent(cfg).run(state)
    from terminal.agents.alert_agent import AlertAgent
    arep = AlertAgent(cfg).run(state, enabled_rules=dict(s.get("ui_rules", {})),
                               auto_trade=bool(s.get("ui_auto_trade", False)))
    s["orch"].reports[rep.name] = rep
    s["orch"].reports[rrep.name] = rrep
    s["orch"].reports[arep.name] = arep
    s["zone_dirty"] = False


def global_zone_rows(cfg: Config):
    """Zones for commodities / indices / FX from real Yahoo candles."""
    s = st.session_state
    cached = s.get("global_rows")
    if cached and time.time() - cached[0] < 600:
        return cached[1]
    yh = YahooProvider(cfg)
    rows = []
    if yh.is_available():
        from terminal.services.candles import CandleService
        svc = CandleService(yh, cache_dir=f"{cfg.cache_dir}/candles")
        for inst in GLOBAL_INSTRUMENTS:
            df = svc.get(inst["yahoo"], "1h")
            if df is None or df.empty:
                continue
            spot = 0.0
            q = s.get("state").global_quotes.get(inst["key"]) if s.get("state") else None
            spot = q.ltp if q else float(df["close"].iloc[-1])
            zones = detect_zones(df, spot=spot, max_zones=1,
                                 legout_mult=cfg.zone_legout_mult,
                                 max_wick_pct=cfg.zone_max_wick_pct,
                                 tight_base=cfg.zone_eod_filter)
            if not zones:
                continue
            e20, e50 = ema(df, 20), ema(df, 50)
            bias = "BUY" if (spot > e20 > 0 and (e50 == 0 or e20 > e50)) else (
                "SELL" if (spot < e20 and (e50 == 0 or e20 < e50)) else "AVOID TRADE")
            row = build_zone_row(inst["key"], "1h", zones[0], spot, spot,
                                 rr=cfg.zone_target_rr, sl_buffer_atr=cfg.zone_sl_buffer_atr,
                                 capital=cfg.capital, risk_pct=cfg.risk_per_trade_pct,
                                 ai_score=f"{int(max(-10, min(10, round((rsi(df,14)-50)/5))))}/10",
                                 ai_bias=bias)
            row["Near Timeframe"] = "1h"
            rows.append(row)
    s["global_rows"] = (time.time(), rows)
    return rows


